// @ts-nocheck
// Arimo (Apache License 2.0, from Google Fonts): Arial's metrics, with the Sámi letters the PDF's
// built-in Helvetica lacks. Registers "Arimo" with jsPDF for printed letters and replies.
import { jsPDF } from "jspdf"
const regular = '';
const bold = '';
var callAddFont = function () {
    this.addFileToVFS('Arimo-Regular.ttf', regular);
    this.addFont('Arimo-Regular.ttf', 'Arimo', 'normal');
    this.addFileToVFS('Arimo-Bold.ttf', bold);
    this.addFont('Arimo-Bold.ttf', 'Arimo', 'bold');
};
jsPDF.API.events.push(['addFonts', callAddFont])
